def solve(words):
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    return counts

def solve(text):
    left = 0
    right = len(text) - 1
    while left < right:
        if text[left] != text[right]:
            return False
        left += 1
        right -= 1
    return True

def solve(numbers):
    evens = []
    for number in numbers:
        if number % 2 == 0:
            evens.append(number)
    return sorted(evens)

def solve(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            return len(f.read().split())
    except FileNotFoundError:
        return 0

def solve(path):
    result = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            text = line.strip()
            if text:
                result.append(text)
    return result

def solve(values):
    converted = []
    rejected = 0
    for text in values:
        try:
            converted.append(int(text))
        except ValueError:
            rejected += 1
    return converted, rejected

def solve(path, text):
    with open(path, "a", encoding="utf-8") as f:
        return f.write(text + "\n")
